#!/usr/bin/env python3
"""Print printable_table.go: the code points str.isprintable() rejects (CPython 3.11, Unicode 14).

    ~/cf-test/.venv/bin/python server/internal/logx/testdata/gen_printable.py > server/internal/logx/printable_table.go
"""
import sys
import unicodedata

assert sys.version_info[:2] == (3, 11)
ranges = []
start = None
for cp in range(0x110000):
    bad = not chr(cp).isprintable()
    if bad and start is None:
        start = cp
    if not bad and start is not None:
        ranges.append((start, cp - 1))
        start = None
if start is not None:
    ranges.append((start, 0x10FFFF))
print('// Code generated by testdata/gen_printable.py (Python %s, Unicode %s); DO NOT EDIT.' % (sys.version.split()[0], unicodedata.unidata_version))
print()
print('package logx')
print()
print('// nonPrintable lists, as inclusive ranges, the code points for which Python 3.11\'s')
print('// str.isprintable() is false. Lone surrogates are not representable in Go strings.')
print('var nonPrintable = [][2]rune{')
for a, b in ranges:
    print('\t{0x%X, 0x%X},' % (a, b))
print('}')
